CREATE TABLE IF NOT EXISTS owners(id uuid PRIMARY KEY,email text UNIQUE NOT NULL,password_hash text NOT NULL);
CREATE TABLE IF NOT EXISTS stores(id uuid PRIMARY KEY,name text NOT NULL,timezone text NOT NULL DEFAULT 'Asia/Colombo',visible_epoch uuid,last_synced timestamptz,forecast jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS memberships(owner_id uuid NOT NULL REFERENCES owners(id),store_id uuid NOT NULL REFERENCES stores(id),PRIMARY KEY(owner_id,store_id));
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,owner_id uuid NOT NULL REFERENCES owners(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS enrollments(code_hash text PRIMARY KEY,store_id uuid NOT NULL REFERENCES stores(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS devices(id uuid PRIMARY KEY,store_id uuid NOT NULL REFERENCES stores(id),token_hash text NOT NULL UNIQUE,revoked boolean NOT NULL DEFAULT false,epoch uuid,last_sequence bigint NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS one_source_device ON devices(store_id) WHERE NOT revoked;
CREATE TABLE IF NOT EXISTS sync_events(store_id uuid NOT NULL,device_id uuid NOT NULL,epoch uuid NOT NULL,sequence bigint NOT NULL,event_id uuid NOT NULL,digest text NOT NULL,PRIMARY KEY(device_id,epoch,sequence),UNIQUE(store_id,event_id));
CREATE TABLE IF NOT EXISTS analytics_records(store_id uuid NOT NULL,epoch uuid NOT NULL,table_name text NOT NULL,record_id text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(store_id,epoch,table_name,record_id));
CREATE INDEX IF NOT EXISTS analytics_by_store ON analytics_records(store_id,epoch,table_name);
CREATE TABLE IF NOT EXISTS questions(id uuid PRIMARY KEY,owner_id uuid NOT NULL,store_id uuid NOT NULL,question text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
DO $$ BEGIN IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='ajith_analytics_reader') THEN CREATE ROLE ajith_analytics_reader NOLOGIN NOSUPERUSER NOBYPASSRLS; END IF; END $$;
ALTER TABLE analytics_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE analytics_records FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_records ON analytics_records;
CREATE POLICY tenant_records ON analytics_records USING (store_id=nullif(current_setting('app.store_id',true),'')::uuid) WITH CHECK (store_id=nullif(current_setting('app.store_id',true),'')::uuid);
ALTER TABLE stores ENABLE ROW LEVEL SECURITY;
ALTER TABLE stores FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_stores ON stores;
CREATE POLICY tenant_stores ON stores USING (id=nullif(current_setting('app.store_id',true),'')::uuid) WITH CHECK (id=nullif(current_setting('app.store_id',true),'')::uuid);
CREATE OR REPLACE VIEW analytics_data WITH (security_invoker=true) AS SELECT table_name,record_id,data FROM analytics_records WHERE epoch=(SELECT visible_epoch FROM stores WHERE id=nullif(current_setting('app.store_id',true),'')::uuid);
GRANT USAGE ON SCHEMA public TO ajith_analytics_reader;
GRANT SELECT ON analytics_records,analytics_data TO ajith_analytics_reader;
GRANT SELECT(id,visible_epoch) ON stores TO ajith_analytics_reader;
DO $$ BEGIN EXECUTE format('GRANT ajith_analytics_reader TO %I',current_user); END $$;
